{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-latest-models-only",
  "version": "0.1.0",
  "description": "OpenCode V2 plugin that hides models older than 3 months, toggled with /toggle-old-models",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/4nkitd/opencode-latest-models-only.git"
  },
  "keywords": ["opencode", "opencode-v2", "plugin", "models", "models.dev"],
  "type": "module",
  "exports": {
    ".": "./index.ts"
  },
  "files": ["index.ts", "README.md", "LICENSE"],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "check": "bun run typecheck && bun run test"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.22",
    "@types/bun": "latest",
    "typescript": "^5.9.3"
  },
  "engines": {
    "node": ">=20",
    "bun": ">=1.3.0"
  }
}
